(function(){
  'use strict';
  const D=SimData,KEY='la-moncloa-save-v1';
  const $=(q,root=document)=>root.querySelector(q);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=(v,d=1)=>Number(v).toLocaleString('es-ES',{maximumFractionDigits:d,minimumFractionDigits:d});
  const initials=n=>n.trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
  const icons={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',parliament:'M3 9 12 3l9 6H3Zm2 3v7m5-7v7m4-7v7m5-7v7M2 22h20',economy:'M3 18 9 12l4 3 8-10M15 5h6v6M3 22h19',society:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7a4 4 0 0 1 0 8m5 9v-2a4 4 0 0 0-3-3.87',cabinet:'M8 6V3h8v3M3 7h18v14H3V7Zm0 5h18m-11 0v3h4v-3',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3a17 17 0 0 1 0 18 17 17 0 0 1 0-18Z',vote:'m9 11 2 2 4-4M5 11l-3 4v6h20v-6l-3-4M6 3h12v12H6V3Zm-4 12h4m12 0h4',history:'M3 12a9 9 0 1 0 3-6.7M3 3v5h5m4-1v5l3 2',arrow:'M4 12h16m-6-6 6 6-6 6',health:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6V3Z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 9 3 3 5-5',leaf:'M20 3C8 2 2 8 5 15s15 6 15-12ZM4 21 16 9',education:'m2 8 10-5 10 5-10 5L2 8Zm4 3v7c4 3 8 3 12 0v-7m4-3v9',coin:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 6v12m4-9c-1-3-8-2-8 1s8 1 8 4-7 4-8 1',capital:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',pin:'M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 1 1 14 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',more:'M5 12h.01M12 12h.01M19 12h.01',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',save:'M5 3h13l3 3v15H3V3h2Zm2 0v6h10V3M7 21v-8h10v8',news:'M5 3h16v18H5V3Zm0 6H2v10a2 2 0 0 0 3 2M9 7h8m-8 4h8m-8 4h3m3 0h2m-8 3h8'};
  const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.home}"/></svg>`;
  const pages=[['resumen','Centro de mando','home'],['congreso','Congreso','parliament'],['economia','Economía','economy'],['sociedad','Sociedad','society'],['gobierno','Tu Gobierno','cabinet'],['territorios','Territorios','map'],['exteriores','Exteriores','globe'],['elecciones','Elecciones','vote'],['cronica','Crónica y legado','history']];
  let sim,view='resumen',scene=null,modalAction=null,historyFilter='all',audioContext=null,storageWarning=false;
  try{const raw=localStorage.getItem(KEY);sim=raw?SimEngine.fromJSON(raw):new SimEngine();}catch{sim=new SimEngine();storageWarning=true;}
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)sim.s.settings.motion=false;
  const formatDate=(turn=sim.s.turn,short=false)=>new Date(sim.s.startYear,turn,1).toLocaleDateString('es-ES',{month:short?'short':'long',year:'numeric'});
  function save(){try{localStorage.setItem(KEY,sim.export());$('#save-indicator').innerHTML='<i></i> Partida guardada';}catch{$('#save-indicator').textContent='Guardado no disponible';if(!storageWarning){storageWarning=true;toast('Exporta tu partida','El navegador no permite guardar aquí. Descarga una copia desde Ajustes.',true);}}}
  function toast(title,text='',error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=`<strong>${esc(title)}</strong><p>${esc(text)}</p>`;$('#toasts').appendChild(el);setTimeout(()=>el.remove(),5500);while($('#toasts').children.length>3)$('#toasts').firstChild.remove();}
  function sound(kind=true){if(!sim.s.settings.audio)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const melodies={decision:[440,554,660],month:[330,440,494],law:[392,494,587,784],election:[262,330,392,523,659],menu:[520],error:[196,147]};const notes=melodies[kind===false?'error':kind===true?'decision':kind]||melodies.decision;const start=audioContext.currentTime;notes.forEach((frequency,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),t=start+i*.085;osc.type=kind==='month'?'triangle':'sine';osc.frequency.setValueAtTime(frequency,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(kind==='menu'?.014:.03,t+.012);gain.gain.exponentialRampToValueAtTime(.0001,t+.22);osc.connect(gain).connect(audioContext.destination);osc.start(t);osc.stop(t+.24);osc.onended=()=>{osc.disconnect();gain.disconnect();};});}catch{}}
  function result(r,options={}){if(r.error){toast('No se ha realizado la acción',r.error,true);sound(false);return false;}sound(r.election?'election':r.votes?(r.pass?'law':'error'):r.title==='Comienza un nuevo mes'?'month':'decision');save();render();if(r.votes)showVote(r);else if(r.election)showElection();else if(r.ended)showEnding();else if(options.effects&&r.effects)showModal(r.title,`<p>${esc(r.text)}</p>${effects(r.effects)}<div class="button-row"><button class="primary-button" data-action="close">Continuar ${icon('arrow',15)}</button></div>`);else toast(r.title,r.text);return true;}
  function effects(values){return `<div class="effect-tags">${Object.entries(values||{}).map(([k,v])=>{const info=D.metrics[k],group=D.groups.find(g=>g.id===k),good=v*(info?.good||1)>0;return `<span class="effect-tag ${good?'':'negative'}">${esc(info?.name||group?.name||k)} ${v>0?'+':''}${num(v,Number.isInteger(v)?0:1)}${info?.unit==='%'?' pp':''}</span>`;}).join('')}</div>`;}
  function progress(label,value,color='',suffix='/100'){return `<div class="progress-row"><div class="progress-label"><span>${esc(label)}</span><strong>${num(value,0)}${suffix}</strong></div><div class="progress-track"><i class="${color}" style="width:${Math.max(0,Math.min(100,value))}%"></i></div></div>`;}
  function resourceStrip(){return `<div class="resources-strip"><div class="resource">${icon('capital',15)}<span>Capital <span class="resource-label">político</span></span> <strong>${num(sim.s.capital,0)}<span class="resource-label"> / 100</span></strong></div><div class="resource">${icon('clock',15)}<span>Acciones</span><span class="resource-dots">${[0,1,2].map(i=>`<i class="${i<sim.s.actions?'filled':''}"></i>`).join('')}</span></div><div class="resource">${icon('coin',15)}<span class="resource-label">Tesorería</span><strong>${num(sim.s.metrics.cash,1)} mil M€</strong></div></div>`;}
  function heading(title,subtitle,label='TU PAÍS, TUS DECISIONES'){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="turn-block"><div class="turn-date"><strong>${formatDate()}</strong><small>Mandato ${sim.s.term} · ${sim.monthsRemaining} meses hasta las urnas</small></div><button class="primary-button" data-action="next" ${sim.s.ended?'disabled':''}>${sim.s.election?'Investidura':'Siguiente mes'} ${icon('arrow',15)}</button></div></div>`;}
  function spark(key){let data=sim.s.series.slice(-12).map(x=>x[key]);if(data.length<2)data=[data[0]-0.4,data[0]-.25,data[0]-.35,data[0]-.05,data[0]-.15,data[0]];const min=Math.min(...data)-.1,max=Math.max(...data)+.1;const points=data.map((v,i)=>`${i/(data.length-1)*72},${24-(v-min)/(max-min)*21}`).join(' ');return `<svg class="sparkline" viewBox="0 0 74 27" aria-hidden="true"><polyline points="${points}" fill="none" stroke="${D.metrics[key].good>0?'#8caa7d':'#bd9973'}" stroke-width="1.5"/></svg>`;}
  function metricCard(key,ico){const m=D.metrics[key],value=sim.s.metrics[key],prev=sim.s.series.length>1?sim.s.series.at(-2)[key]:value,delta=value-prev,good=delta*m.good>=0;return `<article class="metric-card"><div class="metric-top"><span>${m.name}</span>${icon(ico,16)}</div><div class="metric-main"><span class="metric-value">${num(value)}<small>${m.unit}</small></span><span class="metric-delta ${good?'':'bad'}">${delta>=0?'↗':'↘'} ${num(Math.abs(delta))}</span></div><div class="metric-foot">${key==='approval'?'Apoyo a la gestión del Gobierno':key==='growth'?'Ritmo anual estimado':key==='unemployment'?'Población activa':'Deuda pública sobre el PIB'}</div>${spark(key)}</article>`;}
  function sceneCard(mode='palace'){const title=mode==='palace'?'Un país por delante.<br>Todo por decidir.':mode==='congress'?'Donde las ideas<br>se convierten en leyes.':'España en el mundo.';return `<section class="card scene-card"><div class="scene-heading"><div class="eyebrow">${mode==='palace'?'PALACIO DE LA MONCLOA':mode==='congress'?'EL HEMICICLO':'DIPLOMACIA Y COOPERACIÓN'}</div><h2>${title}</h2><p class="scene-subtitle">${mode==='palace'?'La presidencia es tuya. El futuro está por escribir.':mode==='congress'?'350 representantes. Una mayoría por construir.':'Las decisiones también cruzan fronteras.'}</p></div><div class="scene-location">${icon('pin',11)} ${mode==='europe'?'EUROPA':'MADRID, ESPAÑA'}</div><div class="scene-viewport" id="scene-viewport" data-mode="${mode}"></div><div class="scene-hint">Arrastra para girar · Pellizca para acercar</div><div class="scene-bottom"><div class="scene-label"><i></i> ${mode==='palace'?'VISTA DE LA PRESIDENCIA':mode==='congress'?'VISTA DEL CONGRESO':'VISTA INTERNACIONAL'}</div><div class="scene-controls"><button data-camera="left" aria-label="Girar la cámara a la izquierda">‹</button><button data-camera="right" aria-label="Girar la cámara a la derecha">›</button><button data-camera="out" aria-label="Alejar">−</button><button data-camera="in" aria-label="Acercar">+</button><button data-camera="reset" aria-label="Restablecer cámara">⟲</button></div></div></section>`;}
  function eventCard(){const ev=sim.event;return `<section class="card event-card"><div class="card-header"><h2>${icon('news')}En tu mesa</h2><span class="priority"><i></i> ${ev?'DECISIÓN PENDIENTE':'AL DÍA'}</span></div>${ev?`<div class="event-main"><div class="event-category">${esc(ev.category)} <span> / </span> CONSEJO DE MINISTROS</div><h3>${esc(ev.title)}</h3><p class="event-description">${esc(ev.body)}</p><div class="decision-list">${ev.options.map((o,i)=>`<button class="decision-option" data-decision="${i}"><span class="decision-letter">${String.fromCharCode(65+i)}</span><span><strong>${esc(o.label)}</strong><small>${o.delayed?'Resultados a medio plazo':i===0?'Una respuesta desde el Gobierno':'Explora sus consecuencias'}</small></span><span class="decision-cost">${o.cost} ◇</span><span class="decision-arrow">›</span></button>`).join('')}</div></div><div class="event-foot"><span>◇ Coste en capital político · 1 acción</span><button class="text-button" data-action="defer">Aplazar ↗</button></div>`:`<div class="event-empty"><div class="empty-emblem">${icon('check',38)}</div><h3>${sim.s.ended?'Tu historia ya está escrita.':sim.s.election?'Las urnas han hablado.':'Una decisión, un nuevo rumbo.'}</h3><p>${sim.s.ended?'Explora tu legado o comienza una nueva presidencia.':sim.s.election?'Construye una nueva mayoría para continuar gobernando.':'Aprovecha las acciones restantes para impulsar una ley, negociar o revisar las cuentas.'}</p><button class="text-button mt-16" data-view="${sim.s.ended?'cronica':sim.s.election?'elecciones':'congreso'}">${sim.s.ended?'Ver mi legado':sim.s.election?'Ver resultados':'Ir al Congreso'} ${icon('arrow',13)}</button></div>`}</section>`;}
  function dashboard(){const m=sim.s.metrics,latest=sim.s.history.filter(h=>h.type!=='achievement').slice(0,2);return heading('El futuro se decide aquí.','Bienvenido a la presidencia. Cada decisión deja huella.')+statusBanner()+`<div class="metrics-grid">${metricCard('approval','society')}${metricCard('growth','economy')}${metricCard('unemployment','cabinet')}${metricCard('debt','coin')}</div><div class="dashboard-grid">${sceneCard()}${eventCard()}</div>${resourceStrip()}<div class="lower-grid"><section class="card"><div class="card-header"><h2>El pulso del país</h2><span class="pill">ESTADO NACIONAL</span></div><div class="card-body">${progress('Estabilidad del Gobierno',m.stability)}${progress('Calidad de los servicios públicos',(m.health+m.education)/2,'gold')}${progress('Acceso a la vivienda',m.housing,'coral')}<button class="text-button mt-16" data-view="sociedad">Todos los indicadores ${icon('arrow',13)}</button></div></section><section class="card"><div class="card-header"><h2>La agenda del Gobierno</h2>${icon('clock',15)}</div><div class="card-body"><div class="agenda-item"><span class="agenda-icon">${icon('parliament',16)}</span><div><strong>Una mayoría que cuidar</strong><p>${sim.coalitionSeats} escaños · ${sim.coalitionSeats>=176?'Gobierno con mayoría':'Gobierno en minoría'}</p></div><button class="text-button" data-view="congreso" aria-label="Abrir Congreso">↗</button></div><div class="agenda-item"><span class="agenda-icon">${icon('economy',16)}</span><div><strong>Las cuentas del mandato</strong><p>Balance anual: ${num(sim.fiscal().balance)} mil M€</p></div><button class="text-button" data-view="economia" aria-label="Abrir presupuestos">↗</button></div><div class="agenda-item"><span class="agenda-icon">${icon('vote',16)}</span><div><strong>La próxima cita con las urnas</strong><p>${sim.monthsRemaining} meses · cada voto cuenta</p></div><button class="text-button" data-view="elecciones" aria-label="Abrir elecciones">↗</button></div></div></section><section class="card"><div class="card-header"><h2>La prensa del día</h2><span class="subtle">LA GACETA · FICTICIA</span></div><div class="card-body">${latest.map((h,i)=>`<div class="press-story"><small>${i===0?'POLÍTICA NACIONAL':'EL PAÍS EN MARCHA'}</small><p>«${esc(h.title)}»</p><span>${formatDate(h.turn,true)} · Edición de la simulación</span></div>`).join('')}</div></section></div>`;}
  function statusBanner(){if(sim.s.ended)return `<div class="end-banner"><div><h2>Todo mandato deja un legado.</h2><p>${esc(sim.s.ended.reason)}</p></div><button class="primary-button" data-action="ending">Ver mi legado ${icon('arrow',15)}</button></div>`;if(sim.s.election)return `<div class="end-banner"><div><h2>Es la hora de formar Gobierno.</h2><p>Las elecciones han terminado. Busca apoyos para la investidura.</p></div><button class="primary-button" data-action="election">Ver resultados ${icon('arrow',15)}</button></div>`;if(sim.s.metrics.stability<30)return `<div class="notice danger">El Gobierno está en una situación frágil. Negocia apoyos y mejora la estabilidad para evitar una moción de censura.</div>`;return '';}
  function hemicycle(parties=sim.s.parties){const dots=[];const colors=parties.flatMap(p=>Array(p.seats).fill(p.color));let n=0;const rows=[34,40,44,49,55,61,67];for(let row=0;row<rows.length;row++){const r=56+row*16;for(let j=0;j<rows[row];j++){const a=Math.PI-j/(rows[row]-1)*Math.PI;dots.push(`<circle cx="${190+Math.cos(a)*r}" cy="${176-Math.sin(a)*r}" r="4.4" fill="${colors[n++]||'#ddd'}"/>`);}}return `<svg class="hemicycle" viewBox="0 0 380 210" role="img" aria-label="Reparto de los 350 escaños del Congreso">${dots.join('')}<text x="190" y="157" text-anchor="middle" style="font:29px Georgia;fill:#3c5540">350</text><text x="190" y="175" text-anchor="middle" style="font:8px 'Segoe UI';letter-spacing:1.5px;fill:#9ba68e">ESCAÑOS</text><path d="M190 14v45" stroke="#bfb89e" stroke-dasharray="2 3"/><text x="190" y="202" text-anchor="middle" style="font:9px 'Segoe UI';fill:#9ba68e">MAYORÍA ABSOLUTA · 176</text></svg>`;}
  function congress(){return heading('La política es llegar a acuerdos.','Negocia, suma apoyos e impulsa tus leyes.','EL CONGRESO DE LOS DIPUTADOS')+statusBanner()+`<div class="content-grid"><div class="section-stack"><section class="card"><div class="card-header"><h2>El arco parlamentario</h2><span class="pill">350 ESCAÑOS</span></div><div class="card-body">${hemicycle()}<div class="hemicycle-legend">${sim.s.parties.map(p=>`<span><i class="legend-dot" style="background:${p.color}"></i>${esc(p.short)} ${p.seats}</span>`).join('')}</div><div class="majority-summary"><strong>${sim.coalitionSeats}<span class="subtle"> / 176</span></strong><p>Escaños del Gobierno · ${sim.coalitionSeats>=176?'Mayoría parlamentaria':'Necesitas apoyos externos'}</p></div></div></section>${sceneCard('congress')}</div><section class="card"><div class="card-header"><h2>Construir una mayoría</h2><span class="subtle">RELACIÓN / 100</span></div><div class="card-body">${sim.s.parties.map((p,i)=>`<div class="party-row"><div class="party-logo" style="color:${p.color}">${p.short}</div><div class="party-info"><strong>${esc(p.name)}</strong><small>${i===0?'Tu grupo':`${num(p.relation,0)} de relación · ${sim.s.coalition.includes(p.id)?'Socio de Gobierno':'Oposición'}`}</small></div><span class="party-seats">${p.seats}</span>${i?`<div class="party-actions"><button class="secondary-button" data-talk="${p.id}">Dialogar · 10 ◇</button>${sim.s.coalition.includes(p.id)?`<button class="text-button" data-break="${p.id}">Romper pacto</button>`:`<button class="text-button" data-pact="${p.id}">Proponer pacto · 20 ◇</button>`}</div>`:''}</div>`).join('')}<p class="budget-note">Cada diálogo o pacto consume una acción. Los pactos necesitan 55 de relación e incluyen un compromiso a seis meses.</p>${sim.s.promises.filter(p=>!p.done).map(p=>`<div class="notice mt-16">Pacto con ${esc(sim.s.parties.find(x=>x.id===p.party).name)}: ${D.metrics[p.metric].name} ≥ ${num(p.target)} antes de ${formatDate(p.due)}.</div>`).join('')}</div></section></div><section class="card mt-22"><div class="card-header"><h2>Tu agenda legislativa</h2><span class="pill">${sim.s.laws.length} LEYES APROBADAS</span></div><div class="card-body"><p class="intro-text">Los apoyos son una previsión: puede haber disciplina de voto imperfecta. Necesitas 176 votos y puedes someter una ley al pleno cada mes.</p><div class="law-list">${D.laws.map(l=>{const approved=sim.s.laws.includes(l.id),support=sim.supportFor(l).reduce((n,p)=>n+p.yes,0);return `<article class="law-card ${approved?'approved':''}"><span class="pill">${l.area}</span><h3>${l.name}</h3><p>${l.description}</p>${effects(l.effects)}<div class="law-support ${support>=176?'positive-text':''}">${approved?'✓ Aprobada y en vigor':`${support} apoyos previstos · ${l.cost} ◇ · 1 acción`}</div><button class="secondary-button" data-law="${l.id}" ${approved?'disabled':''}>${approved?'En vigor':'Preparar votación'} ${approved?'':icon('arrow',13)}</button></article>`;}).join('')}</div></div></section>${resourceStrip()}`;}
  const budgetLabels={health:'Sanidad',education:'Educación y ciencia',welfare:'Pensiones y protección social',infrastructure:'Infraestructuras',security:'Seguridad y defensa',climate:'Transición ecológica',incomeTax:'Tipo efectivo sobre la renta',vat:'IVA simulado',corporateTax:'Impuesto de sociedades'};
  const budgetLimits={health:[5,30],education:[4,20],welfare:[12,40],infrastructure:[2,18],security:[3,15],climate:[1,15],incomeTax:[15,38],vat:[10,28],corporateTax:[15,35]};
  function budgetControl(key){const [min,max]=budgetLimits[key],tax=['incomeTax','vat','corporateTax'].includes(key);return `<div class="budget-control"><label for="budget-${key}">${budgetLabels[key]}<output id="output-${key}">${sim.s.budget[key]}${tax?' %':' puntos'}</output></label><input type="range" id="budget-${key}" data-budget="${key}" min="${min}" max="${max}" value="${sim.s.budget[key]}"><div class="range-ends"><span>${min}</span><span>${tax?'Tipo impositivo':'Esfuerzo presupuestario'}</span><span>${max}</span></div></div>`;}
  function economy(){return heading('Las cuentas también deciden.','Elige dónde invertir y cómo financiarlo.','ECONOMÍA Y PRESUPUESTOS')+statusBanner()+`<div class="metrics-grid">${metricCard('growth','economy')}${metricCard('unemployment','cabinet')}${metricCard('debt','coin')}<article class="metric-card"><div class="metric-top">Inflación ${icon('economy',16)}</div><div class="metric-main"><span class="metric-value">${num(sim.s.metrics.inflation)}<small>%</small></span></div><div class="metric-foot">Variación de los precios en la simulación</div></article></div><div class="content-grid"><section class="card"><div class="card-header"><h2>Presupuestos del Estado</h2><span class="pill">BORRADOR</span></div><div class="card-body"><div class="fiscal-summary" id="fiscal-preview">${fiscalSummary()}</div><p class="intro-text">Los deslizadores fijan prioridades de gasto, expresadas en puntos de esfuerzo. La previsión muestra su coste anual. Los efectos se acumulan cada mes.</p>${Object.keys(budgetLabels).slice(0,6).map(budgetControl).join('')}<h3 class="mt-22">Ingresos e impuestos</h3>${Object.keys(budgetLabels).slice(6).map(budgetControl).join('')}<div class="budget-actions"><span class="subtle">15 ◇ · 1 acción · una revisión por mes</span><button class="primary-button" data-action="budget" ${sim.s.budgetTurn===sim.s.turn?'disabled':''}>${sim.s.budgetTurn===sim.s.turn?'Aprobados este mes':'Aprobar presupuestos'} ${icon('check',15)}</button></div><p class="budget-note">Los tipos, importes y reglas fiscales son simplificaciones de juego. El déficit aumenta las necesidades de financiación; la deuda se ajusta cada mes. La tesorería financia las medidas extraordinarias.</p></div></section><div class="section-stack"><section class="card"><div class="card-header"><h2>Evolución del crecimiento</h2><span class="pill">PIB ANUAL · %</span></div><div class="card-body">${chart('growth')}</div></section><section class="card"><div class="card-header"><h2>Proyectos en marcha</h2>${icon('clock',15)}</div><div class="card-body">${sim.s.delayed.length?sim.s.delayed.map(p=>`<div class="agenda-item"><span class="agenda-icon">${icon('home',15)}</span><div><strong>${esc(p.label)}</strong><p>Entrega prevista: ${formatDate(p.due)}</p>${effects(p.effects)}</div></div>`).join(''):'<div class="empty-state">Las inversiones con efectos diferidos aparecerán aquí.</div>'}</div></section><section class="card"><div class="card-header"><h2>La deuda en el tiempo</h2><span class="pill">DEUDA / PIB</span></div><div class="card-body">${chart('debt')}</div></section></div></div>${resourceStrip()}`;}
  function fiscalSummary(b){const f=sim.fiscal(b);return `<div><small>Ingresos anuales</small><strong>${num(f.revenue,0)}</strong> <em>mil M€</em></div><div><small>Gasto anual</small><strong>${num(f.spending,0)}</strong> <em>mil M€</em></div><div><small>Balance estimado</small><strong class="${f.balance>=0?'positive-text':'negative-text'}">${f.balance>0?'+':''}${num(f.balance)}</strong> <em>mil M€</em></div>`;}
  function chart(key){let data=sim.s.series.slice(-36);if(data.length<2)data=[{...data[0],turn:-1},...data];const values=data.map(d=>d[key]);const min=Math.min(...values)-1,max=Math.max(...values)+1;const x=i=>30+i/(data.length-1)*390,y=v=>165-(v-min)/(max-min)*145;return `<svg class="chart" viewBox="0 0 440 200" role="img" aria-label="Evolución de ${esc(D.metrics[key].name)}"><defs><linearGradient id="fill-${key}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a0b78a" stop-opacity=".2"/><stop offset="1" stop-color="#a0b78a" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(t=>`<path class="chart-grid" d="M30 ${20+t*145}H425"/><text class="chart-label" x="0" y="${24+t*145}">${num(max-t*(max-min))}</text>`).join('')}<path d="M${x(0)} 165 ${data.map((d,i)=>`L${x(i)} ${y(d[key])}`).join(' ')} L${x(data.length-1)} 165Z" fill="url(#fill-${key})"/><polyline class="chart-line" points="${data.map((d,i)=>`${x(i)},${y(d[key])}`).join(' ')}"/><text class="chart-label" x="30" y="190">${formatDate(Math.max(0,data[0].turn),true)}</text><text class="chart-label" x="420" y="190" text-anchor="end">${formatDate(undefined,true)}</text></svg>`;}
  function society(){const descriptions={health:'Acceso y calidad de la atención sanitaria.',education:'Recursos, formación e investigación.',housing:'Facilidad para acceder a un hogar asequible.',climate:'Avance hacia una economía sostenible.',security:'Prevención y capacidad de respuesta.',integrity:'Confianza en las instituciones y transparencia.',infrastructure:'Calidad y conexión de las redes públicas.',stability:'Capacidad del Gobierno para sostener acuerdos.',eu:'Cooperación e influencia en Europa.'};return heading('Detrás de cada cifra, hay personas.','Escucha a quienes viven las consecuencias de tus decisiones.','SOCIEDAD Y BIENESTAR')+`<div class="society-grid">${Object.entries(descriptions).map(([key,description])=>`<article class="card society-card"><div class="metric-top">${D.metrics[key].name} ${icon(key==='health'?'health':key==='climate'?'leaf':key==='education'?'education':key==='security'?'shield':'society',17)}</div><div class="metric-main"><span class="metric-value">${num(sim.s.metrics[key],0)}<small>/100</small></span></div><p>${description}</p><div class="progress-track"><i class="${sim.s.metrics[key]<45?'coral':''}" style="width:${sim.s.metrics[key]}%"></i></div></article>`).join('')}</div><div class="content-grid mt-22"><section class="card"><div class="card-header"><h2>¿Quién te apoya?</h2><span class="pill">APOYO POR COLECTIVO</span></div><div class="card-body">${D.groups.map(g=>`<div class="group-opinion"><span class="group-icon">${g.icon}</span><div class="group-details"><strong>${g.name}</strong><small>${num(g.weight*100,0)} % del peso electoral simulado</small><div class="progress-track mt-16"><i style="width:${sim.s.groups[g.id]}%"></i></div></div><span class="opinion-value">${num(sim.s.groups[g.id],0)}<span class="subtle">%</span></span></div>`).join('')}</div></section><section class="card"><div class="card-header"><h2>La confianza a lo largo del mandato</h2></div><div class="card-body">${chart('approval')}<p class="budget-note">La aprobación combina el apoyo de seis colectivos. Su opinión cambia con tus decisiones, los impuestos, la evolución económica y los servicios.</p></div></section></div>${resourceStrip()}`;}
  function cabinet(){return heading('No se gobierna en solitario.','Un buen equipo también forma parte de tu legado.','EL CONSEJO DE MINISTROS')+`<p class="intro-text">La capacidad de cada ministro influye cada mes en su área. El desgaste reduce su eficacia; una baja lealtad con mucho desgaste perjudica la estabilidad. Renovar cuesta 13 de capital y una acción.</p><div class="cabinet-grid">${sim.s.cabinet.map((m,i)=>`<article class="card minister-card"><div class="minister-portrait">${esc(initials(m.name))}</div><div class="eyebrow">${D.portfolios[i].name}</div><h3>${m.name}</h3><div class="trait">${m.trait}</div>${progress('Capacidad',m.skill)}${progress('Lealtad',m.loyalty,'gold')}${progress('Desgaste',m.fatigue,'coral')}<button class="secondary-button" data-minister="${i}">Cambiar responsable ${icon('arrow',13)}</button></article>`).join('')}</div><section class="card mt-22"><div class="card-header"><h2>El coste de la responsabilidad</h2></div><div class="card-body"><p class="intro-text">Tu equipo mantiene mejoras pequeñas y constantes. En Economía, una gestión eficaz sostiene la actividad; en las demás carteras mejora su indicador. Cambiar nombres no sustituye a financiar los servicios.</p></div></section>${resourceStrip()}`;}
  const mapShapes={11:'45,78 97,62 110,90 95,120 53,124',2:'100,63 148,64 157,87 112,92',5:'150,64 178,68 176,89 157,87',15:'179,67 209,69 217,88 177,90',14:'210,70 233,89 221,115 208,101 216,88',16:'178,91 207,91 209,110 181,110',6:'99,96 155,90 177,94 181,113 205,115 202,155 177,165 117,160 91,137',1:'235,90 260,108 261,153 230,171 202,155 211,116 223,115',8:'260,109 282,116 318,153 291,176 263,154',12:'172,151 194,153 205,172 181,182 164,171',7:'119,165 162,166 179,186 207,173 233,180 241,205 217,228 178,231 139,213 111,209',10:'90,143 117,164 111,208 136,219 119,243 78,232 73,193',0:'78,236 120,247 142,219 174,236 215,233 215,260 188,283 147,289 112,273 96,272',9:'261,159 285,182 272,207 252,240 234,223 245,204 233,178',13:'237,225 252,243 234,263 215,259 217,234',3:'307,212 321,203 338,213 329,225 314,225',4:'39,294 48,288 55,295 48,300 65,304 71,296 78,304 69,311 84,313 91,307 98,315 90,322 61,319',17:'134,309 140,308 141,314 134,315',18:'181,321 186,319 188,325 183,327'};
  function map(){return `<svg class="spain-map" viewBox="20 40 330 300" role="group" aria-label="Mapa esquemático de comunidades y ciudades autónomas">${D.regions.map(r=>{const value=sim.s.regions[r.id].approval;return `<polygon class="map-region" tabindex="0" role="button" aria-label="${esc(r.name)}, apoyo ${num(value,0)} por ciento" data-region="${r.id}" points="${mapShapes[r.id]}" fill="${value>=60?'#6d8c5c':value>=50?'#93a681':value>=40?'#b1b99a':'#c5b294'}"><title>${esc(r.name)} · ${num(value,0)} %</title></polygon>`;}).join('')}<text x="172" y="134" class="map-label">CASTILLA Y LEÓN</text><text x="168" y="205" class="map-label">CASTILLA-LA MANCHA</text><text x="152" y="263" class="map-label">ANDALUCÍA</text><text x="267" y="143" class="map-label">CATALUÑA</text><text x="71" y="94" class="map-label">GALICIA</text><text x="230" y="137" class="map-label">ARAGÓN</text><text x="100" y="195" class="map-label">EXTREMADURA</text><text x="182" y="171" class="map-label">MADRID</text><text x="61" y="335" style="font:7px 'Segoe UI';fill:#9ca68d">CANARIAS · POSICIÓN ESQUEMÁTICA</text></svg>`;}
  function territories(){return heading('Diecinueve formas de mirar al país.','La confianza también se construye sobre el territorio.','COMUNIDADES Y CIUDADES AUTÓNOMAS')+`<div class="content-grid"><div class="section-stack"><section class="card map-card"><div class="card-header"><h2>El mapa de la confianza</h2><span class="pill">TOCA UN TERRITORIO</span></div>${map()}<div class="hemicycle-legend"><span><i class="legend-dot" style="background:#6d8c5c"></i>60 % o más</span><span><i class="legend-dot" style="background:#93a681"></i>50–59 %</span><span><i class="legend-dot" style="background:#b1b99a"></i>40–49 %</span><span><i class="legend-dot" style="background:#c5b294"></i>Menos del 40 %</span></div></section><div class="notice">Mapa esquemático. El juego usa 19 circunscripciones simuladas que suman 350 escaños; simplifica el sistema provincial real. El apoyo territorial modifica el resultado electoral.</div></div><section class="card"><div class="card-header"><h2>La realidad territorial</h2></div><div class="card-body"><table class="region-table"><thead><tr><th>TERRITORIO</th><th>APOYO</th><th>ESCAÑOS</th><th>ACTUAR</th></tr></thead><tbody>${sim.s.regions.map(r=>`<tr><td>${r.name}</td><td>${num(r.approval,0)} %</td><td>${r.seats}</td><td><button class="secondary-button" data-region="${r.id}">Invertir ↗</button></td></tr>`).join('')}</tbody></table><p class="budget-note">Una inversión territorial al mes: 2 mil M€, 10 de capital y una acción. Mejora el apoyo local y las infraestructuras.</p></div></section></div>${resourceStrip()}`;}
  function foreign(){return heading('Una voz propia. Un futuro compartido.','Negocia con tus socios y elige tu papel en el mundo.','EXTERIORES Y COOPERACIÓN')+`<div class="content-grid"><div class="section-stack"><div class="diplomacy-hero"><div class="eyebrow">LA SILLA DE ESPAÑA</div><h2>Las fronteras no detienen<br>las consecuencias.</h2><p>La cooperación europea, el comercio y la ayuda internacional influyen en la economía, la seguridad y la confianza en tu Gobierno.</p>${progress('Relación con los socios europeos',sim.s.metrics.eu,'gold')}</div>${sceneCard('europe')}</div><div><div class="diplomacy-grid" style="margin-top:0">${[['europe','globe','Cumbre europea','Comparte prioridades y refuerza la confianza de los socios.',12],['trade','economy','Misión comercial','Abre oportunidades económicas y comerciales.',12],['climate','leaf','Alianza por el clima','Promueve inversiones y cooperación ambiental.',11],['aid','health','Cooperación humanitaria','Recursos para ayudar y reforzar la confianza institucional.',10]].map(([id,ico,name,desc,cost])=>`<article class="card diplomacy-card">${icon(ico,25)}<h3>${name}</h3><p>${desc}</p><button class="secondary-button" data-diplomacy="${id}">Impulsar · ${cost} ◇</button></article>`).join('')}</div><p class="budget-note">Una iniciativa exterior por mes. Todas consumen una acción; las misiones comercial, climática y humanitaria también usan tesorería.</p></div></div>${resourceStrip()}`;}
  function elections(){const poll=sim.s.election?sim.s.election.result:sim.poll(),forecast=sim.s.election?sim.s.election.result:sim.allocate(poll);return heading('El poder se vuelve a ganar.','Una encuesta no es una elección. Escucha, explica y moviliza.','EL CAMINO A LAS URNAS')+statusBanner()+`<div class="content-grid"><div class="section-stack"><section class="card"><div class="card-header"><h2>${sim.s.election?'Resultado electoral':'Intención de voto'}</h2><span class="pill">${sim.s.election?'ESCRUTINIO COMPLETO':'SONDEO SIMULADO'}</span></div><div class="card-body">${poll.map(p=>`<div class="poll-row"><span class="poll-name">${esc(p.name)}</span><div class="poll-track"><i style="width:${p.vote}%;background:${p.color}"></i></div><strong class="poll-value">${num(p.vote)} %</strong></div>`).join('')}<p class="budget-note">${sim.s.election?'El escrutinio ha terminado. La investidura requiere 176 escaños.':'El sondeo combina aprobación y movilización. La previsión de escaños aplica D’Hondt en circunscripciones simplificadas y un umbral local del 3 %. En las elecciones hay variación territorial adicional.'}</p></div></section><section class="card"><div class="card-header"><h2>${sim.s.election?'El nuevo Congreso':'Proyección de escaños'}</h2><span class="subtle">${sim.monthsRemaining} MESES HASTA LAS URNAS</span></div><div class="card-body">${hemicycle(forecast)}<div class="hemicycle-legend">${forecast.map(p=>`<span><i class="legend-dot" style="background:${p.color}"></i>${p.short} ${p.seats}</span>`).join('')}</div></div></section></div><div class="section-stack"><section class="card"><div class="card-header"><h2>La calle también decide</h2>${icon('society',17)}</div><div class="card-body"><div class="campaign-actions">${[['rally','society','Encuentro ciudadano','Conecta con trabajadores y jóvenes.',10],['debate','news','Debate público','Explica tu proyecto a empresas y servicios públicos.',14],['rural','map','Ruta por los pueblos','Acércate al mundo rural.',9],['listen','history','Escucha ciudadana','Recoge propuestas y mejora la transparencia.',7]].map(([id,ico,name,desc,cost])=>`<button class="campaign-action" data-campaign="${id}">${icon(ico,23)}<span><strong>${name}</strong><small>${desc}</small></span><span class="campaign-cost">${cost} ◇</span></button>`).join('')}</div><p class="budget-note">Una acción de campaña por mes. La movilización se enfría con el tiempo; gobernar bien también cuenta. Los actos usan capital político, sin gasto de tesorería pública.</p></div></section><section class="card"><div class="card-header"><h2>El calendario electoral</h2></div><div class="card-body"><div class="big-number">${sim.monthsRemaining}<span class="subtle"> meses</span></div><p class="budget-note">Cada legislatura dura 48 meses. Puedes adelantar las elecciones tras seis meses de mandato. Convocar cuesta 25 de capital y una acción.</p><button class="${sim.s.election?'primary':'secondary'}-button full-width mt-16" data-action="${sim.s.election?'election':'early-election'}">${sim.s.election?'Formar Gobierno':'Convocar elecciones anticipadas'} ${icon('vote',16)}</button></div></section><section class="card"><div class="card-header"><h2>La movilización de tu proyecto</h2></div><div class="card-body">${progress('Impulso de campaña',sim.s.campaign/12*100,'gold',' %')}<p class="budget-note">La confianza entre partidos es decisiva después de las urnas. Los socios necesitan al menos 45 de relación y una distancia ideológica compatible para apoyar tu investidura.</p></div></section></div></div>${resourceStrip()}`;}
  function chronicle(){const entries=sim.s.history.filter(h=>historyFilter==='all'||h.type===historyFilter);return heading('Lo que quedará de tus decisiones.','Una historia que solo tú podías escribir.','CRÓNICA DEL MANDATO')+`<div class="content-grid"><section class="card"><div class="card-header"><h2>El archivo de la presidencia</h2><button class="text-button" data-action="export-chronicle">Descargar crónica ${icon('save',13)}</button></div><div class="card-body"><div class="filter-row"><select id="history-filter" aria-label="Filtrar la crónica">${[['all','Toda la historia'],['decision','Decisiones'],['law','Leyes'],['election','Elecciones'],['pact','Acuerdos'],['project','Proyectos'],['achievement','Logros']].map(([id,name])=>`<option value="${id}" ${historyFilter===id?'selected':''}>${name}</option>`).join('')}</select><span class="subtle">${entries.length} entradas</span></div><div class="timeline">${entries.length?entries.map(h=>`<article class="timeline-item ${esc(h.type)}"><small>${formatDate(h.turn).toUpperCase()}</small><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p></article>`).join(''):'<div class="empty-state">Todavía no hay entradas de este tipo.</div>'}</div></div></section><div class="section-stack"><section class="card"><div class="card-header"><h2>El legado de ${esc(sim.s.name)}</h2></div><div class="card-body"><div class="statistics-grid"><div><strong>${sim.s.statistics.decisions}</strong><small>DECISIONES</small></div><div><strong>${sim.s.statistics.laws}</strong><small>LEYES</small></div><div><strong>${sim.s.turn}</strong><small>MESES AL FRENTE</small></div></div>${D.missions.map(m=>{const complete=sim.s.missions.includes(m.id),value=sim.s.metrics[m.metric],pct=complete?100:m.reverse?Math.min(100,m.target/value*100):Math.min(100,value/m.target*100);return `<article class="mission-card ${complete?'complete':''}"><div class="mission-badge">${icon(complete?'check':'capital',17)}</div><div><h3>${m.name}</h3><p>${m.description}${complete?' · Cumplido':''}</p><div class="progress-track"><i class="${complete?'gold':''}" style="width:${pct}%"></i></div></div></article>`;}).join('')}</div></section><section class="card"><div class="card-header"><h2>La historia que elegiste</h2></div><div class="card-body"><h3 style="font-family:var(--serif);font-size:23px">${D.scenarios.find(s=>s.id===sim.s.scenario).name}</h3><p class="budget-note">${D.scenarios.find(s=>s.id===sim.s.scenario).description} Todos los dirigentes, partidos, datos y sucesos de la partida son ficticios. Los escenarios históricos son reinterpretaciones para jugar.</p></div></section></div></div>`;}
  const builders={resumen:dashboard,congreso:congress,economia:economy,sociedad:society,gobierno:cabinet,territorios:territories,exteriores:foreign,elecciones:elections,cronica:chronicle};
  function render(){
    const oldContainer=scene?.container;
    $('#main').innerHTML=builders[view]();
    $('#navigation').innerHTML=pages.map(([id,name,ico],i)=>`${i===7?'<div class="nav-group-label">TU MANDATO</div>':''}<a href="#${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span class="nav-label">${name}</span>${id==='congreso'?`<span class="nav-count">350</span>`:''}</a>`).join('');
    $('#mobile-navigation').innerHTML=[['resumen','Inicio','home'],['congreso','Congreso','parliament'],['economia','Economía','economy'],['elecciones','Elecciones','vote']].map(([id,label,ico])=>`<a href="#${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')+`<button data-action="more" class="${['sociedad','gobierno','territorios','exteriores','cronica'].includes(view)?'active':''}">${icon('more')}Más</button>`;
    $('#mobile-command').innerHTML=`<div><strong>${num(sim.s.capital,0)} ◇</strong><span>Capital político</span></div><div><strong>${sim.s.actions} / 3</strong><span>Acciones disponibles</span></div><button data-action="${sim.s.ended?'ending':'next'}">${sim.s.ended?'Ver legado':sim.s.election?'Investidura':'Mes siguiente'} ${icon('arrow',15)}</button>`;
    $('#breadcrumb').textContent=pages.find(p=>p[0]===view)[1];$('#avatar').textContent=initials(sim.s.name);$('#sidebar-term').textContent=`MANDATO ${sim.s.term} · ${sim.s.startYear+Math.floor(sim.s.turn/12)}`;
    const target=$('#scene-viewport');
    if(target){if(scene?.renderer||scene?.container.classList.contains('scene-fallback')){target.replaceWith(oldContainer);const mode=target.dataset.mode;scene.sim=sim;scene.visible=true;scene.setMode(mode);scene.resize();}else{scene=new PresidencyScene(target,sim);}}else if(scene){scene.visible=false;}
  }
  function navigate(page){if(!builders[page])return;if(view!==page)sound('menu');view=page;render();window.scrollTo({top:0,behavior:'instant'});if(location.hash!==`#${page}`)history.replaceState(null,'',`#${page}`);}
  function showModal(title,body,subtitle=''){const modal=$('#modal');modalAction=null;$('#modal-content').innerHTML=`<div class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="modal-close" data-action="close" aria-label="Cerrar">${icon('close',15)}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
  function closeModal(){$('#modal').close();modalAction=null;}
  function confirm(title,body,callback,label='Confirmar',subtitle=''){showModal(title,`${body}<div class="button-row"><button class="primary-button" data-action="confirm">${label} ${icon('arrow',15)}</button><button class="secondary-button" data-action="close">Volver</button></div>`,subtitle);modalAction=callback;}
  function decision(index){const ev=sim.event,op=ev?.options[index];if(!op)return;confirm(op.label,`<p>${esc(op.description)}</p><div class="decision-detail"><strong>Consecuencias inmediatas</strong>${effects(op.effects)}${op.delayed?`<strong>Efectos dentro de ${op.delayed.months} meses</strong>${effects(op.delayed.effects)}`:''}</div><p>Coste: <strong>${op.cost} de capital político</strong> y <strong>1 acción</strong>.</p>`,()=>{const r=sim.resolveEvent(index);if(!r.error)closeModal();result(r);},'Tomar esta decisión',esc(ev.title));}
  function showVote(r){showModal(r.pass?'Una idea se convierte en ley.':'Esta vez no hay mayoría.',`<div class="tally-result"><strong>${r.votes.reduce((n,p)=>n+p.yes,0)}</strong><p>VOTOS A FAVOR · ${r.text}</p></div>${r.votes.map(p=>`<div class="poll-row"><span class="poll-name">${esc(p.name)}</span><div class="poll-track"><i style="width:${p.yes/Math.max(1,p.seats)*100}%;background:${p.color}"></i></div><strong class="poll-value">${p.yes}/${p.seats}</strong></div>`).join('')}${effects(r.effects)}<div class="button-row"><button class="primary-button" data-action="close">Continuar</button></div>`);}
  function showElection(){if(!sim.s.election){navigate('elecciones');return;}const r=sim.s.election.result,own=r[0];showModal('Las urnas han hablado.',`<p>Tu partido obtiene <strong>${own.seats} escaños</strong>. Busca 176 apoyos para gobernar. Los grupos con poca confianza o una ideología muy distante no aceptarán la coalición.</p>${hemicycle(r)}<form id="investiture-form">${r.slice(1).map(p=>{const available=p.relation>=45&&Math.abs(p.ideology-sim.s.ideology)<=3;return `<label class="ally-choice"><input type="checkbox" name="ally" value="${p.id}" ${available?'':'disabled'}><span><i class="legend-dot" style="background:${p.color}"></i>${esc(p.name)}<small class="subtle"> · ${available?'Disponible':'Sin acuerdo posible'}</small></span><strong>${p.seats}</strong></label>`;}).join('')}<div class="tally-result"><strong id="investiture-total">${own.seats}</strong><p>ESCAÑOS REUNIDOS · NECESITAS 176</p></div><div class="button-row"><button class="primary-button" type="submit">Presentarme a la investidura</button><button class="danger-button" type="button" data-action="defeat">Aceptar el relevo</button></div></form>`);}
  function showEnding(){const score=Math.round(sim.s.metrics.approval*0.35+sim.s.missions.length*6+sim.s.laws.length*2+sim.s.term*4);showModal('Este es tu legado.',`<p>${esc(sim.s.ended?.reason||'Tu mandato continúa. Este es el balance hasta hoy.')}</p><div class="tally-result"><strong>${score}</strong><p>PUNTOS DE LEGADO · ${sim.s.missions.length} OBJETIVOS CUMPLIDOS</p></div><div class="statistics-grid"><div><strong>${sim.s.turn}</strong><small>MESES</small></div><div><strong>${sim.s.statistics.decisions}</strong><small>DECISIONES</small></div><div><strong>${sim.s.laws.length}</strong><small>LEYES</small></div></div><p>Tu balance y todas las decisiones permanecen en la crónica. Puedes exportar la partida antes de empezar de nuevo.</p><div class="button-row"><button class="primary-button" data-action="new-game">Nueva presidencia</button><button class="secondary-button" data-action="export">Exportar partida</button><button class="text-button" data-action="see-chronicle">Ver la crónica →</button></div>`);}
  function help(){showModal('Gobernar es elegir.',`<p>Tu objetivo es mejorar el país, mantener la confianza del Congreso y conseguir otro mandato. Empiezas con 177 escaños de coalición y una primera decisión sobre la mesa.</p>${[['01','Decide con consecuencias','Resuelve el asunto de cada mes. Pulsa una opción para ver sus efectos antes de confirmar. Puedes aplazarlo, con un coste de confianza.'],['02','Administra tu margen','Tienes tres acciones por mes. Decidir, negociar, legislar o hacer campaña consume una. El capital político se recupera al avanzar.'],['03','Construye acuerdos','Impulsa leyes con 176 votos, cuida a los socios y cumple tus compromisos. Los ministros y los presupuestos influyen cada mes.'],['04','Vuelve a ganarte el voto','Cada 48 meses hay elecciones. La aprobación, la campaña y los territorios importan. Necesitas una mayoría para tu siguiente investidura.']].map(([n,t,p])=>`<div class="help-step"><span>${n}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}<h3>La escena es 3D de verdad.</h3><p>Arrastra para girar, pellizca para acercar o utiliza los botones. En móvil, la navegación está abajo; «Más» abre el resto de áreas.</p><p class="budget-note">Partida ficticia, sin conexión y sin cuentas. El guardado es automático en este navegador. Exporta una copia para cambiar de dispositivo. No se usan datos políticos en tiempo real.</p><div class="button-row"><button class="primary-button" data-action="close">Entrar al Consejo ${icon('arrow',15)}</button><button class="secondary-button" data-action="new-game">Personalizar partida</button></div>`);}
  function settings(){showModal('Tu partida, a tu manera.',`<div class="settings-row"><span>Sonido de la interfaz<small>Efectos de decisiones, votos, elecciones y cambios de mes.</small></span><input type="checkbox" id="setting-audio" aria-label="Activar sonido" ${sim.s.settings.audio?'checked':''}></div><div class="settings-row"><span>Animaciones 3D<small>Desactívalas para reducir el movimiento.</small></span><input type="checkbox" id="setting-motion" aria-label="Activar animaciones" ${sim.s.settings.motion?'checked':''}></div><div class="settings-row"><span>Calidad de gráficos<small>Usa modo ligero para ahorrar batería.</small></span><select id="setting-quality" aria-label="Calidad de los gráficos">${[['auto','Equilibrada'],['low','Ligera · móvil'],['high','Alta']].map(([v,n])=>`<option value="${v}" ${sim.s.settings.quality===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="settings-row"><span>${esc(sim.s.name)}<small>${esc(sim.s.partyName)} · ${formatDate()} · ${esc(sim.s.difficulty)}</small></span><span class="pill">GUARDADO LOCAL</span></div><div class="save-actions"><button class="secondary-button" data-action="export">${icon('save',15)} Exportar partida</button><button class="secondary-button" data-action="import">${icon('history',15)} Importar partida</button><button class="secondary-button" data-action="help">${icon('news',15)} Cómo jugar</button><button class="danger-button" data-action="new-game">Nueva presidencia</button></div><p class="budget-note">El autoguardado pertenece a este navegador y dirección. Si borras sus datos, desaparece. Una exportación JSON permite continuar en otro dispositivo. Ningún dato sale de tu equipo.</p>`);}
  function newGame(){showModal('Un país. Tu propia historia.',`<p>Comienza una nueva partida. Al confirmar se sustituirá el autoguardado actual; puedes <button class="text-button" data-action="export">exportarlo antes</button>.</p><form id="new-game-form"><div class="form-two"><div class="form-field"><label for="player-name">Tu nombre</label><input id="player-name" name="name" value="${esc(sim.s.name)}" required maxlength="40" autocomplete="off"></div><div class="form-field"><label for="party-name">Nombre de tu partido</label><input id="party-name" name="partyName" value="Horizonte" required maxlength="35" autocomplete="off"></div></div><div class="form-two"><div class="form-field"><label for="ideology">Orientación de tu proyecto</label><select id="ideology" name="ideology"><option value="-2">Izquierda</option><option value="-1">Centroizquierda</option><option value="0" selected>Centro</option><option value="1">Centroderecha</option><option value="2">Derecha</option></select></div><div class="form-field"><label for="difficulty">Dificultad</label><select id="difficulty" name="difficulty"><option value="relajado">Relajada · más margen</option><option value="normal" selected>Normal · un reto equilibrado</option><option value="dificil">Difícil · presión constante</option></select></div></div><div class="form-field"><label>Elige el punto de partida</label><input type="hidden" name="scenario" id="scenario" value="mandato"><div class="scenario-grid">${D.scenarios.map((s,i)=>`<button class="scenario-option ${i===0?'active':''}" type="button" data-scenario="${s.id}" aria-pressed="${i===0}"><small>${s.year} · ${s.tag}</small><strong>${s.name}</strong><p>${s.description}</p></button>`).join('')}</div></div><p class="budget-note">Los escenarios históricos son historias alternativas con partidos ficticios y reglas comunes; no reconstrucciones documentales. Tu proyecto empieza con un pacto de centroizquierda, que podrás renegociar.</p><div class="button-row"><button class="primary-button" type="submit">Asumir la presidencia ${icon('arrow',15)}</button><button class="secondary-button" type="button" data-action="close">Seguir mi partida</button></div></form>`);}
  function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
  function exportGame(){download(sim.export(),`la-moncloa-${sim.s.startYear+Math.floor(sim.s.turn/12)}-mes-${sim.s.turn+1}.json`,'application/json');toast('Copia descargada','Importa este archivo desde Ajustes para continuar en otro dispositivo.');}
  function more(){showModal('Tu mesa de Gobierno.',`<div class="mobile-menu-grid">${pages.map(([id,name,ico])=>`<button class="mobile-menu-item" data-menu-view="${id}">${icon(ico,23)}${name}</button>`).join('')}<button class="mobile-menu-item" data-action="settings">${icon('save',23)}Ajustes y partida</button></div>`);}
  const actions={
    close:closeModal,help,settings,profile:()=>showModal('La presidencia.',`<div class="minister-portrait" style="float:none">${esc(initials(sim.s.name))}</div><h3>${esc(sim.s.name)}</h3><p>${esc(sim.s.partyName)} · Mandato ${sim.s.term}<br>${D.scenarios.find(s=>s.id===sim.s.scenario).name} · ${formatDate()}</p><div class="button-row"><button class="primary-button" data-action="new-game">Personalizar una nueva partida</button><button class="secondary-button" data-action="close">Volver</button></div>`),more,'new-game':newGame,export:exportGame,import:()=>$('#import-file').click(),
    confirm:()=>modalAction?.(),next:()=>{if(sim.s.election){showElection();return;}result(sim.nextTurn());},
    defer:()=>confirm('Aplazar también tiene un coste.',`<p>El asunto quedará sin resolver. Pierdes 3 puntos de estabilidad y algo de apoyo ciudadano. No consume acción ni capital.</p>`,()=>{closeModal();result(sim.deferEvent());},'Aplazar el asunto'),
    budget:()=>{const b=Object.fromEntries([...document.querySelectorAll('[data-budget]')].map(el=>[el.dataset.budget,Number(el.value)]));confirm('Estas son tus prioridades.',`<p>Los niveles de inversión e impuestos se mantendrán hasta que vuelvas a modificarlos. Aprobar consume 15 de capital y una acción.</p><div class="fiscal-summary">${fiscalSummary(b)}</div>`,()=>{const r=sim.setBudget(b);if(!r.error)closeModal();result(r);},'Aprobar presupuestos');},
    'early-election':()=>confirm('Devolver la palabra a las urnas.',`<p>Convocar cuesta 25 de capital y una acción. El resultado se calculará con el apoyo actual, la movilización y la realidad territorial. Una elección puede poner fin a tu mandato.</p>`,()=>{const r=sim.callElection(true);if(!r.error)closeModal();result(r);},'Convocar elecciones'),
    election:showElection,defeat:()=>confirm('Un relevo también es democracia.',`<p>Aceptar el resultado pondrá fin a esta partida. Tu crónica y tus logros seguirán disponibles hasta que comiences una nueva.</p>`,()=>{closeModal();result(sim.acceptDefeat());showEnding();},'Aceptar el relevo'),ending:showEnding,
    'see-chronicle':()=>{closeModal();navigate('cronica');},
    'export-chronicle':()=>{const content=`LA MONCLOA · CRÓNICA DE ${sim.s.name.toUpperCase()}\n${sim.s.partyName} · ${sim.s.turn} meses de gobierno\nSimulación ficticia\n\n`+sim.s.history.slice().reverse().map(h=>`${formatDate(h.turn)} · ${h.title}\n${h.text}\n`).join('\n');download(content,'mi-legado-la-moncloa.txt','text/plain;charset=utf-8');}
  };
  document.addEventListener('click',e=>{
    const el=e.target.closest('button,[data-view]');if(!el||el.disabled)return;
    if(el.dataset.action){actions[el.dataset.action]?.();return;}
    if(el.dataset.menuView){closeModal();navigate(el.dataset.menuView);return;}
    if(el.dataset.view){navigate(el.dataset.view);return;}
    if(el.dataset.camera){scene?.control(el.dataset.camera);return;}
    if(el.dataset.decision!==undefined){decision(Number(el.dataset.decision));return;}
    if(el.dataset.scenario){$('#scenario').value=el.dataset.scenario;document.querySelectorAll('[data-scenario]').forEach(b=>{const active=b===el;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});return;}
    if(el.dataset.talk){result(sim.negotiate(el.dataset.talk));return;}
    if(el.dataset.pact){const p=sim.s.parties.find(p=>p.id===el.dataset.pact);confirm(`Un pacto con ${esc(p.name)}.`,`<p>Sumarías ${p.seats} escaños. El acuerdo requiere una relación de 55 o más, cuesta 20 de capital y una acción e incluye un compromiso que deberás cumplir en seis meses.</p>`,()=>{const r=sim.negotiate(p.id,'pact');if(!r.error)closeModal();result(r);},'Firmar el pacto');return;}
    if(el.dataset.break){confirm('Cerrar una alianza.',`<p>Romper el pacto cuesta 8 de capital y una acción. Pierdes 8 de estabilidad y 18 de relación con este grupo.</p>`,()=>{const r=sim.dismissCoalition(el.dataset.break);if(!r.error)closeModal();result(r);},'Romper la coalición');return;}
    if(el.dataset.law){const l=D.laws.find(l=>l.id===el.dataset.law),support=sim.supportFor(l).reduce((n,p)=>n+p.yes,0);confirm(l.name,`<p>${l.description}</p>${effects(l.effects)}<div class="decision-detail"><strong>${support} apoyos previstos · mayoría: 176</strong><p>Las desviaciones en la disciplina de voto pueden cambiar el resultado. El intento consume ${l.cost} de capital y una acción, aunque no se apruebe.</p></div>`,()=>{const r=sim.voteLaw(l.id);if(!r.error)closeModal();result(r);},'Someter al pleno');return;}
    if(el.dataset.minister!==undefined){const index=Number(el.dataset.minister);showModal('Un nuevo equipo para el reto.',`<p>Relevar al responsable de ${D.portfolios[index].name.toLowerCase()} cuesta 13 de capital y una acción. La renovación elimina su desgaste y resta un punto de estabilidad.</p><div class="section-stack mt-16">${D.ministers.map((m,i)=>sim.s.cabinet.some(c=>c.name===m.name)?'':`<button class="decision-option" data-replace="${index}" data-candidate="${i}"><span class="party-logo">${esc(initials(m.name))}</span><span><strong>${m.name}</strong><small>${m.trait} · capacidad ${m.skill} · lealtad ${m.loyalty}</small></span><span class="decision-arrow">›</span></button>`).join('')}</div>`);return;}
    if(el.dataset.replace!==undefined){const r=sim.replaceMinister(Number(el.dataset.replace),Number(el.dataset.candidate));if(!r.error)closeModal();result(r);return;}
    if(el.dataset.campaign){result(sim.campaign(el.dataset.campaign));return;}
    if(el.dataset.diplomacy){const type=el.dataset.diplomacy;confirm('Una iniciativa más allá de las fronteras.',`<p>La misión consumirá una acción y capital político. Las misiones comercial, climática y humanitaria también utilizan tesorería. Solo puedes impulsar una iniciativa exterior al mes.</p>`,()=>{const r=sim.diplomacy(type);if(!r.error)closeModal();result(r,{effects:true});},'Impulsar iniciativa');return;}
    if(el.dataset.region!==undefined)openRegion(Number(el.dataset.region));
  });
  function openRegion(id){const r=sim.s.regions[id];confirm(r.name,`<p>Apoyo al Gobierno: <strong>${num(r.approval,0)} %</strong> · ${r.seats} escaños en la simulación.</p><div class="decision-detail"><strong>Plan territorial de servicios e infraestructuras</strong>${effects({cash:-2,infrastructure:2,rural:1})}<p>El apoyo en este territorio aumenta 9 puntos. Coste: 10 de capital y una acción. Solo un plan territorial por mes.</p></div>`,()=>{const out=sim.investRegion(id);if(!out.error)closeModal();result(out);},'Aprobar inversión');}
  document.addEventListener('click',e=>{const region=e.target.closest('.map-region');if(region)openRegion(Number(region.dataset.region));});
  document.addEventListener('keydown',e=>{const region=e.target.closest?.('.map-region');if(region&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openRegion(Number(region.dataset.region));}});
  document.addEventListener('input',e=>{if(e.target.dataset.budget){const b=Object.fromEntries([...document.querySelectorAll('[data-budget]')].map(el=>[el.dataset.budget,Number(el.value)]));const key=e.target.dataset.budget;$(`#output-${key}`).textContent=e.target.value+(['incomeTax','vat','corporateTax'].includes(key)?' %':' puntos');$('#fiscal-preview').innerHTML=fiscalSummary(b);}});
  document.addEventListener('change',e=>{
    if(e.target.id==='setting-audio'){sim.s.settings.audio=e.target.checked;save();sound();}
    if(e.target.id==='setting-motion'){sim.s.settings.motion=e.target.checked;save();}
    if(e.target.id==='setting-quality'){sim.s.settings.quality=e.target.value;scene?.resize();save();}
    if(e.target.id==='history-filter'){historyFilter=e.target.value;render();}
    if(e.target.name==='ally'){const own=sim.s.parties[0].seats,selected=[...document.querySelectorAll('[name=ally]:checked')].reduce((n,x)=>n+sim.s.parties.find(p=>p.id===x.value).seats,own);$('#investiture-total').textContent=selected;}
  });
  document.addEventListener('submit',e=>{
    if(e.target.id==='new-game-form'){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim(),partyName=String(f.get('partyName')).trim();if(!name||!partyName){toast('Completa tu perfil','El nombre y el partido no pueden estar vacíos.',true);return;}const settings=sim.s.settings;sim=new SimEngine({name,partyName,ideology:Number(f.get('ideology')),scenario:f.get('scenario'),difficulty:f.get('difficulty')});sim.s.settings=settings;scene?.dispose();scene=null;closeModal();save();navigate('resumen');toast('La presidencia es tuya',`${name}, el Consejo de Ministros te espera.`);}
    if(e.target.id==='investiture-form'){e.preventDefault();const allies=new FormData(e.target).getAll('ally'),r=sim.formGovernment(allies);if(!r.error)closeModal();result(r);}
  });
  $('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw new Error('El archivo supera el tamaño máximo de 3 MB.');const imported=SimEngine.fromJSON(await file.text());confirm('Continuar otra historia.',`<p>Partida de <strong>${esc(imported.s.name)}</strong>, ${esc(imported.s.partyName)}. Fecha: ${new Date(imported.s.startYear,imported.s.turn,1).toLocaleDateString('es-ES',{month:'long',year:'numeric'})}. Esta importación sustituirá el autoguardado actual.</p>`,()=>{sim=imported;scene?.dispose();scene=null;closeModal();save();navigate('resumen');toast('Partida restaurada','Puedes seguir tu mandato desde donde lo dejaste.');},'Importar y continuar');}catch(err){toast('No se ha importado la partida',err.message,true);}e.target.value='';});
  $('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
  window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(builders[page])navigate(page);});
  window.addEventListener('pagehide',()=>{save();scene?.dispose();scene=null;});
  window.addEventListener('pageshow',e=>{if(e.persisted)render();});
  view=builders[location.hash.slice(1)]?location.hash.slice(1):'resumen';render();save();
  if(sim.s.briefing){sim.s.briefing=false;save();setTimeout(()=>toast('Bienvenido a La Moncloa','Empiezas con 3 acciones. Abre «?» para conocer las reglas o personaliza tu partida en Ajustes.'),800);}
})();
